"Anyone remember why the sky is a portal?":"Kuna anayekumbuka kwa nini anga ni lango?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Wanasema ukiruka kwenye shimo unatokea kwa adui. Sitajaribu.",
"The Swarm painted their visors red again. Show-offs.":"Nyuki wa Swarm wamepaka visori vyao rangi nyekundu tena. Wajisifu.",
"Ore, ore… when do we get some oil?":"Madini ghafi, madini ghafi… mafuta ya kulainisha tutapewa lini?",
"I dreamt I was a toaster. It was peaceful.":"Niliota mimi ni kikaango cha mkate. Kulikuwa na amani.",
"Quiet. Too quiet.":"Kimya. Kimya mno.",
"See that? Our base is above the Swarm base again. Portals, man.":"Mmeona? Juu ya kambi ya Kundi la Nyuki kuna kambi yetu tena. Malango bwana.",
"Diman, if you're reading this — we need a vacation.":"Diman, kama unasoma hili — tunahitaji likizo.",
"YOU":"WEWE",
"patched":"imetengenezwa",
"pinned":"amebanwa",
