"Not a Portal Meteor save or an unsupported version":"Si hifadhi ya Portal Meteor au toleo lisilosaidiwa",
"Browser storage is full":"Hifadhi ya kivinjari imejaa",
"Battle loaded: {0}":"Vita vimepakiwa: {0}",
"Autosaved":"Imehifadhiwa kiotomatiki",
"robot war · the sky is a portal":"vita vya roboti · anga ni lango",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Karibu kwenye kimondo! Wewe ni roboti ya kivita ya Consortium. Tazama pande zote kwa kipanya na tembea kwa WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: gusa Shift kuruka kidogo, shikilia Shift kupaa. Nishati hujazwa ukiwa ardhini.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Fyatua — kitufe cha kushoto. Lenga — kitufe cha kulia: sahihi zaidi, na kukuza. Fyatua risasi chache.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Kujaza upya — R. Risasi huumiza zaidi masafa ya kati, mita 20–50.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Roketi — Q. Dhidi ya vifaru na majengo. Rusha roketi.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Juu ni amri ya mkakati wa AI. Kimbia kwenye mishale ya kijani: kwenye njia una mbio kali. Teka kituo — simama karibu na alama.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Kikosi chako kinakulinda: picha zao na afya yao ziko kushoto. Wakibaki nyuma, watakuomba usubiri.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — kubadili haraka kitengo bila kutoka vitani: ruka kwenye kikosi au kifaru kilicho karibu zaidi na pambano. Jaribu.",
"Next to a tank or turret press E to take control. Or just carry on.":"Ukiwa karibu na kifaru au turret, bonyeza E ili kuudhibiti. Au endelea tu na safari.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Sasa mkakati. Gusa \"◩ Mkakati\" juu kulia — mwonekano wa juu wa uwanja wa vita.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Sasa mkakati. Bonyeza {0} (au \"◩ Mkakati\" juu kushoto) — mwonekano wa juu wa uwanja wa vita.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Katika mkakati Mwongozaji anakusaidia: kisanduku cha juu kinasema cha kufanya, fremu inaonyesha kitufe, pete inaonyesha mahali kwenye ramani. Kamilisha ushauri wake watatu.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Chagua kikosi na ugonge kitufe cha kijani \"▶ Controlar\" — unarudi vitani kama askari huyo. Wakati unapiga risasi, mkakati wa AI anaongoza jeshi.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Chagua kikosi na bonyeza {0} au \"▶ Controlar\" ya kijani — unarudi vitani kama askari huyo (bila uteuzi — wako mwenyewe). Wakati unapiga risasi, mkakati wa AI anaongoza jeshi.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Mafunzo yamekamilika! Swarm wanaanza mashambulizi. Kila la heri, askari!",
