"The sonar is alive: enemies within 140 m revealed for 40 s":"Sonari imewaka: maadui ndani ya m 140 wanaonekana kwa s 40",
"Side task complete":"Kazi ya pembeni imekamilika",
"Shortcut available: fly straight up through the dome — you will come out near the target.":"Kuna njia ya mkato: ruka moja kwa moja juu kupitia kuba — utatokea karibu na lengo.",
