"Squads jet up through the dome portal and land at the enemy.":"Vikosi vinaruka kwa jetpack kupitia lango la kuba na kutua kwa adui.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Dhibiti mwenyewe askari, kifaru au turel uliochaguliwa. Kitufe hicho hicho vitani kinakurudisha kwenye mkakati.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"Askari 4: mshambuliaji, mpiga risasi mzito, mrusha roketi, tabibu.",
