"New in v6.2":"Mapya katika v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Mwonekano mpya wa madini ghafi: mishipa ni fuwele za zumaridi zinazong'aa zenye pande kwenye basalti nyeusi na cheche na ukungu wa kijani; Extractor ni msingi wa pembe sita wenye kuba ya sega la asali na mnara wa wavu wenye taa ya kijani juu (mstari na bendera katika rangi ya timu)",
"New in v6.1":"Mapya katika v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Darasa unalopendelea kama Battlefield (U, namba baada ya kufa): utazaliwa upya ndani yake ikiwezekana",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Magari kwa mtazamo wa kwanza (V — nje/kabini); msaada mdogo wa kulenga — kwenye Mipangilio",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Kutoka kwenye kiini sasa ni rahisi: Space — kwenye shimo, B — kapsuli hadi juu; athari za uwezo huisha ukifa",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Maendeleo yasiyoisha: majenerali na Marshali ★, viwango vya taaluma, ustadi wa silaha na viambatisho, medali, mikataba ya kila siku — skrini ya Taaluma",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Mkakati: zoom laini ya gurudumu, aikoni na lebo juu ya vitengo (Alt — vyote), paneli ya Wanajeshi / Majengo upande wa kushoto",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"Kitufe cha kulia — nenda na pigana njiani, kitufe cha kulia mara 2 — maandamano ukipiga risasi ukiwa njiani; amri adimu ziko kwenye \"Amri zaidi ▾\"; vitufe havijirudii",
"New in v6":"Mapya katika v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Bunduki za kiwango cha wapiga risasi: risasi za papo hapo, bunduki ya 720 RPM, bunduki-mashine, msukumo wa nyuma, lengo kwa kitufe cha kulia, magazini na kupakia upya kwa R, alama za kugonga",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Mvuto mzito zaidi, mkoba wa roketi unaoitikia haraka, mrukio wa Z au mkoba mara 2 hewani; silaha hairuki tena pamoja unapobadilisha kitengo",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Wahandisi: chagua mhandisi, chagua jengo, weka mchoro; vichimbaji kwenye mishipa ya madini; bofya \"MADINI\" kuona mapato na jinsi ya kuyaongeza",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Vitufe vya kijivu vinaeleza sababu na kutoa suluhisho; vitufe vikubwa zaidi, mstari wa \"Inaendelea\", \"▶ Dhibiti\", Tab ni kitufe kimoja cha hali",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Kamera ya mkakati bila kurukaruka wala kupinduka, zoom hadi kielekezi, ramani ndogo inaweza kuvutwa",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Magari mapya: mvamizi \"Jackal\", MLRS \"Grad\" (roketi zinazofuatilia), chokaa \"Hammer\"; Swarm inapata \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Mkakati wa AI hudumisha amri na haleti kelele za sauti; mapigano yanakuja kwako; B — kuhamisha, Shift+B — kwenye pambano; dira, H — lengo gani",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Uhuru wa kucheza (K) na kwenda peke yako (J), F2 mipangilio ya awali; Esc husimamisha na kuendelea; hifadhi: nafasi, hamisha na leta",
"New in v5.3":"Mapya katika v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Safari ya anga: mvuto mkali zaidi mbali na kimondo, C hewani hufunga breki, msukumo unaelekeza kwa ukali zaidi; hutakwama tena kwenye lango",
"New in v5":"Mapya katika v5",
"Endless war by default and battle scale: normal, large, epic":"Vita visivyoisha kwa chaguo-msingi na ukubwa wa vita: kawaida, kubwa, kubwa sana",
"Save and load the battle (autosave every 3 minutes)":"Hifadhi na pakia pambano (hifadhi ya kiotomatiki kila dakika 3)",
"Squadmates with callsigns: portraits, health and live chatter":"Wenzako wa kikosi wenye majina ya simu: picha, afya na mazungumzo ya moja kwa moja",
"Fog of war in strategy, friends and foes outlined differently":"Ukungu wa vita kwenye mkakati, marafiki na maadui wanaonekana tofauti",
"Camera fly-over when switching, portal aurora instead of rings":"Kamera huruka juu unapobadilisha, mwanga wa lango badala ya pete",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Kazi za pembeni, njia fupi angani, makazi ya msafara wa kwanza yenye vifaa, fuwele, barafu ya mashimo, dhoruba za vumbi",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Mafunzo, hali ya sinema yenye kurekodi video, magari ya kusindikiza kutoka kwa mkakati wa AI",
