"Saves live only in this browser on this device (localStorage). Anyone else who downloads the game gets none of your saves. To move a battle to another computer or browser: \"Export to file\" here → \"Import from file\" there. Autosave runs every 3 minutes of battle and when you quit to the menu.":"Hifadhi zinakaa tu kwenye kivinjari hiki kwenye kifaa hiki (localStorage). Mtu mwingine akipakua mchezo hatapata hifadhi zako. Kuhamisha pambano hadi kompyuta au kivinjari kingine: \"Hamisha kwenye faili\" hapa → \"Leta kutoka faili\" huko. Hifadhi ya kiotomatiki hufanyika kila dakika 3 za pambano na unapotoka kwenda menyu.",
"Import from file…":"Leta kutoka faili…",
"Paste save text":"Bandika maandishi ya hifadhi",
"Import this text":"Leta maandishi haya",
"Copy text":"Nakili maandishi",
"Imported into \"{0}\". Press \"Load\".":"Imeletwa kwenye \"{0}\". Bonyeza \"Pakia\".",
"Sure?":"Una uhakika?",
"Empty slot":"Nafasi tupu",
"The file was sent to downloads. ":"Faili imetumwa kwenye vipakuliwa. ",
"If no file appeared (e.g. the game runs inside claude.ai), press \"Copy text\" and paste it into any .json or .txt file.":"Faili isipoonekana (mfano mchezo unaendeshwa ndani ya claude.ai), bonyeza \"Nakili maandishi\" na uyabandike kwenye faili yoyote ya .json au .txt.",
"Could not read the file":"Imeshindwa kusoma faili",
"Paste the save text (Ctrl+V) and press \"Import this text\".":"Bandika maandishi ya hifadhi (Ctrl+V) na bonyeza \"Leta maandishi haya\".",
"Copied.":"Imenakiliwa.",
"Text selected — press Ctrl+C.":"Maandishi yamechaguliwa — bonyeza Ctrl+C.",
"Copied to clipboard.":"Imenakiliwa kwenye ubao wa kunakili.",
