"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Bomu la mkono: shikilia G — utaona mkunjo na mduara wa mlipuko; telezesha kidole kwenye kitufe — pembe; achilia — tupa.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Bomu la mkono: shikilia {0} kwa mkunjo na mduara wa mlipuko, achilia kutupa. Umbali — kwa pembe ya kutazama, gurudumu — nguvu, kitufe cha kulia — kwa chini ya mkono.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Mabomu ya mkono: shikilia G kwa mkunjo wa safari, eneo na mduara wa mlipuko, umbali; achilia kutupa. Umbali kwa pembe ya kutazama, gurudumu — nguvu, kitufe cha kulia — kwa chini ya mkono",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Mabomu ya mkono huruka na kuviringika kwenye miteremko, mlipuko baada ya sekunde 2.5; mabomu 2, kujaza tena sekunde 9; aikoni ya onyo kwa bomu la adui karibu",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Bomu la mkono: shikilia — mkunjo na eneo la mlipuko, achilia — tupa · kasi ya juu ya kifaru",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — shikilia: mkunjo na mduara wa mlipuko vinaonekana, achilia kutupa. Mlipuko baada ya sekunde 2.5, mabomu 2.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Bomu la mkono ({0}): shikilia — mkunjo wa safari, eneo na mduara wa mlipuko, umbali; achilia — tupa; kugusa haraka hutupa mara moja. Umbali kwa pembe ya kutazama, gurudumu — nguvu, kitufe cha kulia — kwa chini ya mkono. Simu: shikilia G na telezesha kidole.",
