"🛠 Developer mode: everything unlocked, endless ore. Arsenal — F8 or the \"🛠 Arsenal\" button.":"🛠 Hali ya msanidi: kila kitu wazi, madini bila kikomo. Ghala la Silaha — F8 au kitufe cha «🛠 Ghala la Silaha».",
"Developer mode off (the match stays flagged — career is not saved)":"Hali ya msanidi imezimwa (mechi inabaki na alama — taaluma haihifadhiwi)",
"Battle saves are disabled in developer mode":"Uhifadhi wa vita umezimwa katika hali ya msanidi",
