"GESTURES":"ISHARA",
"The Polygon works in developer mode only":"Uwanja wa majaribio ni kwa hali ya msanidi tu",
"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ Uwanja wa majaribio: vita visivyoisha katikati ya ramani na vikosi vya nyongeza. X — dhibiti askari huko",
"Polygon off — its units are back under AI command":"Uwanja wa majaribio umezimwa — vitengo vyake vimerudi chini ya amri ya AI",
