"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Gusa \"Lenga\" kukuza. Gusa tena kurudi.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Kikosi chako kinakufuata. Fungua ☰ → \"Simamisha\" → kigae cha \"Kikosi nami\" — kitakuwa \"Peke yangu\".",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Mhandisi amechaguliwa — gusa \"◆ Chimba fuwele\" kwenye kadi yake chini (au gusa fuwele za kijani).",
"Training complete!":"Mafunzo yamekamilika!",
"steps":"hatua",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Unaweza kujenga kituo, kuamuru wanajeshi, kuongoza na kuruka vitani. Kinachofuata — mechi halisi: Mwongozaji atakusaidia mchezoni.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Unaweza kusogea, kuruka, kupiga risasi, kujificha na kuamuru kikosi chako. Kinachofuata — mechi halisi.",
"Real battle":"Vita halisi",
"Again":"Tena",
"done":"imekamilika",
"you are on PC: keyboard and mouse":"uko kwenye PC: kibodi na kipanya",
"you are on a phone: touch screen":"uko kwenye simu: skrini ya kugusa",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Uwanja salama wa majaribio: maadui bado ni vidoli, hakuna anayekupiga. Hatua huhesabiwa tu unapofanya kitendo mwenyewe.",
"Show others (training for the other device)":"Onyesha zingine (mafunzo ya kifaa kingine)",
"Old training (v7.1)":"Mafunzo ya zamani (v7.1)",
"Back to the normal device mode":"Rudi kwenye hali ya kawaida ya kifaa",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Mafunzo ya kifaa kingine yataanzisha upya ukurasa katika hali yake (PC — kipanya na kibodi, simu — mguso; kwenye PC unaweza kujaribu mguso kwenye Chrome: F12 → ikoni ya simu).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Mafunzo ×4: masomo tofauti ya hatua kwa hatua ya \"Mkakati\" na \"Mpiga Risasi\" kwa PC na kwa simu. Uwanja salama wenye vidoli vya mazoezi, kitufe sahihi kinaangaziwa, mishale, vitufe vyenye uhuishaji, kipanya na ishara; hatua inahesabiwa kwa kitendo halisi tu, \"rudia hatua\", maendeleo juu na zawadi mwishoni",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Menyu ya Mafunzo inaonyesha masomo ya kifaa chako; \"Onyesha zingine\" — yote manne kwenye kifaa chochote; \"Mafunzo ya zamani (v7.1)\" bado yapo",
"New in v7.2":"Mapya katika v7.2",
"NEW IN v7.2":"MAPYA KATIKA v7.2",
"No grenades left":"Mabomu ya mkono yameisha",
"Rocket and grenade recharging · {0} s":"Roketi na bomu la mkono vinachajiwa · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Kushoto — tembea, kulia — tazama · gusa adui — roketi / bomu la mkono · gusa mara 2 — reflex · gusa mara 3 — shambulio la mizinga",
"Less":"Pungufu",
"More":"Zaidi",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Gari au jengo la adui liko karibu — ligusa: roketi itaruka.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Maadui wengi — gusa mara 2 mahali patupu upande wa kulia: reflex itapunguza kasi ya muda.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Lenga kundi la maadui na gusa mara 3 — shambulio la mizinga.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Kidole cha kushoto — tembea, cha kulia — tazama. Ukilenga adui, risasi zinapigwa zenyewe.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ upande wa kushoto kando — jetpack: gusa kuruka, shikilia kupaa.",
"Old v7.2 layout":"Mpangilio wa zamani wa v7.2",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Buruta kidole kwenye nusu ya kulia ya skrini — chini ya kidole kitatokea kijiti cha kutazama.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Gusa upande wa kushoto na telezesha — kijiti kitatokea chini ya kidole. Fika kwenye alama ya kijani.",
"Hold the \"Jet\" button at the left edge.":"Shikilia kitufe cha \"Jet\" kando ya kushoto.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Lenga doli la mazoezi kwa kijiti cha kulia — askari wako anapiga risasi mwenyewe kitovu kikiwa juu yake.",
"Tap the dummy on the screen — a rocket flies.":"Gusa doli la mazoezi kwenye skrini — roketi itaruka.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Gusa doli la mazoezi — bomu la mkono litaruka kwa mkunjo, moja kwa moja kwake.",
"Double tap an empty spot on the right quickly.":"Gusa mara 2 haraka mahali patupu upande wa kulia.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Hali nyepesi kwa simu dhaifu: azimio la chini, bila vivuli wala upotoshaji, nusu ya roboti na chembe, kikomo cha FPS 30; hupunguza azimio yenyewe ikiwa FPS < 25. Imewashwa kwa chaguo-msingi kwenye simu (Mipangilio → Picha → \"Hali nyepesi\"; au ?lite=1 / ?lite=0 kwenye kiungo).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Simu: vidhibiti vipya. Kushoto — tembea, kulia — tazama (vijiti vyote viwili hutokea chini ya kidole). Kidole cha kushoto pekee — \"otomatiki\"; kidole cha kulia kikitumika, askari hupiga risasi mwenyewe tu wakati kitovu kiko kwa adui. Gusa adui — roketi au bomu la mkono, gusa mara 2 — reflex, gusa mara 3 — shambulio la mizinga. Kupakia upya kwa otomatiki. Jetpack — kitufe kando ya kushoto. Pembe za chini ziko wazi, ramani ndogo pembeni, vidokezo hufungwa kwa msalaba, lengo linaweza kukunjwa. Mpangilio wa zamani: Mipangilio → Simu.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Vidokezo (madirisha ibukizi na Mwongozaji) — swichi moja kwenye mipangilio. Unayecheza naye (aina ya askari au gari) — lebo \"Wewe: …\" kwenye HUD. Darubini za bunduki na bunduki ya mashine ni wazi. Paneli ya \"Silaha\" iko kulia, inakunjwa na inazimika. \"Peke yako bila kikosi\" (J) imeondolewa. Sauti ya mkakati haijirudii tena mfululizo. Vifaru vina kionyeshi cha mnara dhidi ya mwili. Kielekezi hakipotei tena mwanzoni mwa mafunzo ya mkakati.",
