"Advanced: custom class order":"Ya juu: mpangilio wako wa madaraja",
"Voice of hints & curator":"Sauti ya vidokezo na Mwongozaji",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Simu: njia tatu za vijiti. Kushoto pekee — \"otomatiki\" (sumaku kali, risasi dhaifu). Kulia pekee — kulenga huwaka yenyewe, sumaku kali zaidi, usahihi bora. Vyote viwili — bila kulenga, sumaku na usahihi dhaifu. Kitufe cha 👁 kulia huficha/hurudisha kiolesura.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Simu: mkakati umerahisishwa — mhandisi na majengo tu. Kadi upande wa kushoto (mhandisi, Makao Makuu, Kambi ya Askari…): gusa — kamera inaruka huko, upau wa chini unaonyesha cha kujenga/kuzalisha. \"Vitani\" — juu kushoto. Jeshi linapigana lenyewe. Mkakati kamili — Mipangilio → Simu.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Kudhibiti — swichi mbili: \"Vikosi\" na \"Vifaru\" (vifaru vimezimwa kwa chaguo-msingi kwenye simu — AI huviendesha). Vifaru vikizimwa, E (kwenye simu: kitufe kulia) karibu na gari lako — keti kwenye bunduki yake: linaenda lenyewe, wewe unapiga risasi. Mpangilio wa zamani wa madaraja uko chini ya \"Ya juu\". Kitengo hujibu kwa redio unapokidhibiti.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Vidokezo vya busara: vidokezo vya msingi huzimika baada ya kuanza mara ya 2, lakini mchezo bado utakuonyesha kipengele ambacho hukitumii kamwe. Swichi: msingi / ya juu / adimu, na tofauti kwa sauti ya vidokezo na Mwongozaji.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Reflex huchajiwa kutokana na kuwaua maadui (mfululizo huchaji zaidi). Wenzako wakibaki nyuma au kufa — mkakati hukushushia wapya (ghali kuliko uimarishaji wa kawaida). Picha na sauti za v7.2gfx zimeunganishwa: milipuko ya mawingu, moshi, vifusi, akustika ya mashimo na mashimo makubwa. Tarehe ya toleo sasa ni halisi.",
