"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Taaluma na hifadhi hazibadiliki. Vitani menyu ile ile ni kitufe cha \"🛠 Menyu\" juu kulia{0}.",
"New developer match":"Mechi mpya ya msanidi",
"all unlocked, endless ore, instant build, arsenal":"kila kitu wazi, madini ghafi bila mwisho, ujenzi wa papo hapo, silaha",
"Trainings — all 4":"Mafunzo — yote 4",
"PC and phone (strategy and shooter)":"PC na simu (mkakati na mpiga risasi)",
"Cinema: split screen":"Sinema: skrini mbili",
"strategist bot left, shooter bot right":"roboti-mkakati kushoto, roboti-mpiga risasi kulia",
"Cinema: everything built":"Sinema: kila kitu kimejengwa",
"both bases built and upgraded — for footage":"kambi zote mbili zimejengwa na kuboreshwa — kwa kurekodi",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Hali ya sinema — skrini mbili: roboti-mkakati kushoto (mwonekano wa juu wa kambi na jeshi), roboti-mpiga risasi kulia kwa mtazamo wa kwanza. Vitufe chini (na vitufe S, P): \"Skrini mbili\" na \"★ Yote yamejengwa\" — kambi zote mbili zimejengwa na kuboreshwa kwa kurekodi.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Kiini na handaki kupitia kimondo havipo tena — kimondo ni kigumu kabisa, mapigano ni juu ya uso tu.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Simu: 👁 inaficha kiolesura lakini inabakiza jetpack, ⇆, vijiti na alama ya lengo. \"◎ Lenga\" (kidole cha kulia tu) — sumaku yenye nguvu na upana zaidi; sumaku ya modi zote tatu — Mipangilio → Vidhibiti → \"Za kina\". Kwenye bunduki ya gari kitufe kinasema \"Shuka\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Mafunzo: kwenye simu — ya simu tu, kwenye PC — ya PC tu. Yote 4 yako kwenye menyu ya \"🛠 Msanidi\". Modi ya msanidi na Ghala la Silaha sasa ni menyu moja (vitani — \"🛠 Menyu\" juu kulia, F8 kwenye PC).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Mitindo ya picha \"Dendy (8-bit)\" na \"16-bit\": Mipangilio → Picha → \"Mtindo wa picha\" (maelezo — kitufe cha ⚙). Ikiwa FPS iko chini ya 24 katika sekunde ~10 za kwanza za mechi, Dendy huwaka yenyewe (chini ya 20 — pikseli kubwa zaidi, mistari 120); arifa ya \"rudi kawaida\" hurejesha picha za kawaida milele. Chaguo lako kwenye menyu hushinda kila wakati.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Miundo ya 3D ya mazingira (magofu, mabaki ya magari, ngome) — ile tu iliyopata alama nzuri, hupakiwa inapohitajika. Zima: Mipangilio → Picha → \"Miundo mipya ya 3D ya mazingira\".",
