"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Askari wanaweza kujenga: E (kwenye simu \"Ingia\") kwenye ujenzi wa upande wako — askari wako anajenga, wenzako walio karibu husaidia. Wahandisi wakiwa na shughuli, mkakati hukuomba msaada — alama ya \"UJENZI\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Alama za mkakati: mkakati huweka ⌖ kwenye kundi la maadui karibu nawe — mizinga hupiga sekunde 8 baadaye na MLRS \"Grad\" za upande wako zilizo karibu hurusha mvua ya makombora. Shambulio lako la mizinga kutoka modi ya mkakati pia hupata msaada wa \"Grad\".",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Hifadhi za silaha kwenye makontena ya mizigo na satelaiti zilizoanguka (📦 inaonekana kutoka m 70): E — bunduki nzito kwa sekunde 90, risasi za moto au roketi, pamoja na mabomu ya mkono yaliyojaa. Kutambaa: Ctrl — lala / simama (chini zaidi, lengo thabiti zaidi, lakini polepole).",
