"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Modi tatu za vijiti kwenye simu, mkakati rahisi, kiti cha bunduki ya gari, ardhi yenye makorongo, aina za vikosi, vilipuzi",
