"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ Cheza sasa\" — kitufe cha kwanza cha menyu: safari fupi chini ya anga la lango na moja kwa moja vitani (ruka kwa kitufe chochote au kugusa).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Mapigo yanahisika: sauti ya chuma na cheche, alama ya mauaji kwenye shabaha (kichwani — njano), mfululizo ×N, mtetemo laini kutoka milipuko, mwendo wa polepole kwenye mauaji muhimu. Mtetemo, mwendo wa polepole na kidokezo vinaweza kuzimwa kwenye Mipangilio.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Matokeo ya mechi: muda, waliouawa, mfululizo bora, ★ MVP na kikosi bora, kadi ya mechi — \"⇪ Shiriki\", PNG au kiungo cha mchezo.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Kidokezo cha \"cha kufanya sasa\" upande wa kushoto chini ya rasilimali: amri ya mkakati, kituo cha kuteka, shambulio la Swarm. ✕ au F7 — kunja.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Pigano huhifadhiwa lenyewe ukifunga au ukificha kichupo — \"⟲ Endelea\" kwenye menyu.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 inabaki kwenye menyu ya \"🕘 Toleo la mchezo\" ukipendelea. Takwimu zisizo na jina (bila majina wala barua pepe) sasa hutumwa; zima kwenye Mipangilio.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"Cheza sasa\", mwitikio wa mapigo, matokeo ya mechi yenye kadi ya kushiriki, kidokezo cha \"cha kufanya\", kuhifadhi kiotomatiki",
"and older: v7.5, v7.4, milestones v1–v7.0":"na ya zamani: v7.5, v7.4, hatua kuu v1–v7.0",
"New in v7.6":"Mapya katika v7.6",
"NEW IN v7.6":"MAPYA KATIKA v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Chagua kundi lako kabla ya mechi: \"Consortium\" (askari wazito wenye mavazi ya nguvu, silaha nzito na mizinga) au \"Swarm\" (kasi, makundi ya drone, risasi nzito zenye upotoshaji). AI inacheza lingine. Chaguo hukumbukwa.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Kila kundi lina magari na vitu vyake vya kipekee: Consortium — tanki \"Rhino\" na \"Mabamba ya seramaiti\", Swarm — \"Kundi la drone\" na \"Ranets za fazi\". Usawa umepimwa kwa mechi za boti.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Mashimo ya milipuko: mizinga, roketi na mizinga ya vifaru huchimba mashimo kwenye kimondo — unaweza kutembea na kuendesha ndani yake na kujificha humo.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Mwonekano wa mtu wa 3 kwa askari (V, hukumbukwa; kwenye simu — Vidhibiti) na kamera laini ya gari yenye alama ya mahali mzinga utakapopiga.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 inabaki kwenye menyu ya \"🕘 Toleo la mchezo\" ukipenda kuitumia.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Makundi ya Consortium / Swarm yenye uchaguzi kabla ya mechi, mashimo ya milipuko, mwonekano wa mtu wa 3",
