"Hear that hum? A singing vein. Keep clear!":"Mnasikia mvumo ule? Ni Veio Kuimba. Msikaribie!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Hitilafu! Hewa inazunguka — ni kisima-mzunguko, kizunguke!",
"Rocks floating in the air… A whirlpool! Stay out!":"Mawe yanaelea hewani… Kisima-Mzunguko! Usikaribie!",
"Anomaly ahead — it is crackling with current!":"Hitilafu mbele — inatoa cheche za umeme!",
"Rods and lightning — a Crackler. It loves armour!":"Miiba na radi — Mtatarika. Anapenda ngao!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Hitilafu! Ardhi inatetemeka kwa joto — Chungu cha Moto!",
"Careful, a Brazier underfoot!":"Makini, Chungu cha Moto chini ya miguu!",
"Anomaly — green mist! Acid, hold your breath!":"Hitilafu — ukungu wa kijani! Tindikali, zuia pumzi!",
"The mist is drifting our way, go around!":"Ukungu unatambaa kuelekea kwetu, tuuzunguke!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Hitilafu! Hewa kama kioo — Lenzi, inapinda risasi!",
"Everything is warping… a Lens nearby!":"Kila kitu kinapinda… Lenzi iko karibu!",
"Ha! An enemy walked right into the anomaly!":"Ha! Adui ameingia moja kwa moja kwenye hitilafu!",
"Got him! Lure them into anomalies!":"Amenaswa! Waingize kwenye hitilafu!",
"Beautiful zap! One less tin can.":"Mshindo mzuri kweli! Chuma chakavu kimoja pungufu.",
"The anomaly got me!":"Hitilafu imenikamata!",
"Ow! Don't go in there!":"Aii! Msiingie humo!",
"Discharged! It is dormant now.":"Nimeitoa chaji! Sasa imelala.",
"Clear, the anomaly is discharged.":"Safi, hitilafu imetolewa chaji.",
"They say veins hide artifacts. Only first the vein sings…":"Wanasema mishipa huficha visanii. Ila kwanza mshipa huimba…",
"Throw a bolt first, then walk. Old habit.":"Tupa bolti kwanza, kisha tembea. Mazoea ya zamani.",
"throw a bolt":"tupa bolti",
