" — close":" — funga",
"Supply drop":"Kisanduku cha vifaa",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Hushusha kisanduku karibu na vikosi vyako: risasi, mabomu ya mkono, roketi, vipuri vya silaha, kifaa cha ukarabati.",
"\"Grad\" rocket strike":"Shambulio la roketi la \"Grad\"",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"Roketi 16 kwenye eneo pana baada ya sekunde 3 — kasi na upana kuliko shambulio la mizinga.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Msaada: kisanduku, upelelezi, \"Grad\", mizinga (kisha 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"TAHADHARI: \"Grad\" ya Bầy Đàn incoming",
"Warning! Rocket salvo on our position!":"Tahadhari! Mvurumisho wa roketi kwenye nafasi yetu!",
"take the supply crate":"chukua kisanduku cha vifaa",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Hitilafu za Ajabu kwenye kimondo (wimbi la 1): \"Mshipa Muimbaji\" — fuwele ya kijani inayong'aa, hunguruma na kupiga kila aliye karibu kwa mapigo ya mdundo; \"Kisima-Mzunguko\" huvuta na kurusha, \"Mtatarika\" hutoa radi kati ya miiba, \"Chungu cha Moto\" huwaka chini ya miguu, \"Ukungu wa tindikali\" na \"Lenzi\" (hupinda risasi na mwonekano wako) huelea huku na huko.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Unaweza kuhisi hitilafu mapema (mvumo, mng'ao, mwanga wa joto). Zitoe chaji kwa bomu la mkono, roketi au bolti (E karibu nazo): zitalala, na mara nyingine huacha kisanii chenye faida na hasara. Kikosi kinaonya kwa redio, na maadui (na marafiki) hujikuta wakiingia humo — wavute huko!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Msaada kwa pointi za amri: 4 vitani (📡 kwenye simu) — kisanduku cha vifaa, upelelezi, shambulio la roketi la \"Grad\", shambulio la mizinga kwenye shabaha. Mkakati huona hitilafu kwenye ramani baada ya upelelezi tu.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Visanduku vya vifaa kwenye magofu ya misafara ya zamani, karibu na Makao Makuu na kando ya majengo yaliyokamilika: risasi, mabomu ya mkono, roketi, vipuri vya silaha (hufungua viambatisho).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 inabaki kwenye menyu ya \"🕘 Toleo la mchezo\". Hitilafu zinaweza kuzimwa kwenye Mipangilio.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Hitilafu za Ajabu (\"Mshipa Muimbaji\" na 5 nyingine), kutoa chaji kwa bolti na bomu la mkono, visanii, miito ya msaada kwa PA, visanduku vya vifaa",
"and older: v7.7, v7.6, milestones v1–v7.0":"na ya zamani: v7.7, v7.6, hatua muhimu v1–v7.0",
"New in v7.8":"Mapya katika v7.8",
"NEW IN v7.8":"MAPYA KATIKA v7.8",
"Close":"Funga",
"Anomalies on the meteor":"Hitilafu za Ajabu kwenye kimondo",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ kwenye kona hufungua menyu ya kusitisha: Endelea, Anza upya, Mafunzo, Picha, Mipangilio, Menyu kuu (kwa uthibitisho). Simu: ☰ juu kulia (vitendo vya vita — kigae cha \"⚡ Vitendo\"); PC: kitufe cha \"☰ Menyu\" juu kulia au Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Picha huwa za kawaida kila wakati — Dendy ni kwa chaguo lako tu: swichi ya \"Picha: Kawaida / Dendy (8-bit) / 16-bit\" iko moja kwa moja kwenye menyu kuu na kwenye menyu ya kusitisha. Mchezo ukisuasua sana, kidokezo chenye kitufe cha \"Washa Dendy\" huonekana.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Simu na kompyuta ndogo: kitufe cha kitendo \"✋\" kulia huonekana tu kuna jambo la kufanya karibu — \"Chukua\" (hifadhi, kisanduku), \"Panda\" (gari, mnara wa silaha, bunduki), \"Jenga\", \"Shuka\", \"Bolti\" kwenye hitilafu. Unaweza pia kugusa kitu kilichoangaziwa tu.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Simu, mkakati: shikilia kidole ~0.3 s (simu hutetemeka, pete ya manjano huonekana) kisha buruta — fremu ya kuchagua; kutelezesha kawaida husogeza kamera. Pia kuna kitufe cha \"Fremu\" kulia; kwenye mafunzo hatua ya \"Fremu\" inakubali pia kugusa kikosi.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Simu: vitufe vidogo ni rahisi kubonyeza, orodha ya msaada ya 📡 ni kubwa zaidi, paneli za mkakati hazifuniki tena kusitisha na matokeo. v7.8 inabaki kwenye menyu ya \"🕘 Toleo la mchezo\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menyu ya ☰ kwenye simu na PC, hakuna Dendy ya kiotomatiki, kitufe cha \"✋\" kwenye mguso, kuchagua kwa fremu kwenye simu",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Inasuasua? Jaribu picha za Dendy — ni nyepesi zaidi.",
