"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Shikilia kidole ardhini ~0.3 s — simu hutetemeka na pete ya manjano huonekana — kisha, bila kuinua, buruta: fremu itatokea. Au tumia kitufe cha \"Fremu\" kulia. Kugusa kikosi tu pia kunafaa.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Kwa skrini nzima kwenye iPhone: \"Shiriki\" ⬆ → \"Ongeza kwenye Skrini ya Kwanza\" — mchezo utafunguka bila paneli za Safari.",
"Open portal-meteor.pages.dev for that.":"Kwa hilo fungua tovuti ya portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Gusa — chagua · gusa ardhi — tembea · shikilia — menyu ya amri · shikilia na buruta — fremu · vidole 2 — kukuza",
"Robo-ninja":"Robo-ninja",
