"Shadow protocol":"Itifaki ya \"Kivuli\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Utafiti: hufungua robo-ninja kwenye Kambi ya Askari. Inahitaji Kiwanda cha roboti kilichokamilika.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Shujaa (1 kwa kila upande): hujiteleport kwenye maeneo ya adui mwenyewe na kukata roboti vipande; mdhibiti ili ucheze mwenyewe.",
