"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: hujirukia kwenye maeneo ya adui na kukata mwenyewe. Kijiti / WASD husitisha kwa 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Mwongozo: gusa adui — mruko na pigo, telezesha — kata, 🛡 — zuia",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Mwongozo: kitufe cha kushoto — katana, kitufe cha kulia — zuia, Shift — mruko, Q — shuriken, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: gusa adui — mruko na pigo, telezesha kulia — mkato, ● — shambulio, 🛡 — kinga (kwa wakati = kupangua), ⇑ — mruko wa haraka, ✦ — shuriken, ◎ — teleport, AUTO — mwenyewe",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: kitufe cha kushoto — katana (shikilia — mkato mzito), kitufe cha kulia — kinga (kwa wakati = kupangua), Shift/Z — mruko wa haraka, Q — shuriken, G — teleport hadi kwenye shabaha, kuruka angani — kuruka mara mbili / kukimbia ukutani, {0} — AUTO",
