"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Redio Portal Meteor: nyimbo 100+ za EDMITRY ndani ya mchezo — kitufe cha 📻 (PC: kitufe 5, [ ] — wimbo). Muziki hupakiwa mtandaoni na hauongezi uzito wa mchezo; sauti na kuanza kiotomatiki ziko kwenye Mipangilio, pamoja na kiungo cha \"Sikiliza kwenye Spotify\".",
