"Radio: start by itself in battle":"Redio: ianze yenyewe vitani",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: saibogi mwenye katana. Hufunguliwa katika Kambi ya Askari kwa utafiti wa \"Itifaki ya Kivuli\" (inahitaji Kiwanda cha roboti). Hujiteleport hadi maeneo ya adui, hukata maadui vipande (hakuna damu — cheche), mruko wa haraka, shuriken, duwa na ninja wa adui. Mdhibiti — hali ya AUTO au udhibiti wa mkono (kwenye simu — vitufe vyake).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Redio Portal Meteor: nyimbo 103 za EDMITRY ndani ya mchezo. Kitufe 5 (kinabadilishwa), kwenye simu — ☰ → Mipangilio → Sauti. Sauti na \"anza yenyewe vitani\" ziko kwenye mipangilio; muziki hupungua kwenye milipuko na wakati wa sauti ya redio.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Lugha mpya: Kiuzbeki na Kitajiki — kamili; Kichina, Kihispania, Kireno — kwa sehemu. Chaguo jipya la lugha kwenye menyu karibu na \"Mechi mpya\".",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Simu: \"ficha aikoni\" 👁 hukusanya vitufe vilivyobaki kwenye safu nadhifu pembeni kulia; wima haigongani tena; iPhone — mchezo haugombani na ishara za Safari, na \"Shiriki → Ongeza kwenye Skrini ya Nyumbani\" huuzindua skrini nzima.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Kutoka v7.8.1: menyu ya ☰ pembeni (kusimamisha, kuanza upya, mafunzo, picha), hakuna Dendy kiotomatiki, kitufe cha kitendo ✋ kwenye simu. v7.8.1 na v7.8 zimebaki kwenye menyu ya \"🕘 Toleo la mchezo\".",
