"The bomber took off from the base — into the sky, it will come out over the target":"Mshambuliaji ameruka kutoka kituoni — anaingia angani, atatokea juu ya lengo",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Chagua kikosi → \"▶ Dhibiti\" au gusa mara mbili. Kitufe cha hali juu kulia: Mstratejia → Kamanda → Mpiga Risasi.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Chagua kikosi → \"▶ Dhibiti\" au bofya mara mbili. {0} — kwa mzunguko: Mstratejia → Kamanda → Mpiga Risasi.",
