"Living world: requests, hero quests, breakthrough ops":"Ulimwengu hai: maombi ya wenzako, majukumu ya mashujaa, mageuzi ya vita",
"Living world":"Ulimwengu hai",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Vikosi vyako vinaomba msaada na kukutuza, mashujaa wanatoa majukumu, mstari wa mbele uliokwama unavunjwa kwa operesheni",
"A request":"Ombi la wenzako",
"Breakthrough":"Mageuzi ya vita",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Wenzako wakati mwingine huomba msaada: ujumbe wa redio, kadi ya \"OMBI\" na alama ya ✋. Kikosi kimebanwa — teketeza maadui walio karibu nacho. Zawadi: askari kwa kapsuli kutoka kituoni, bunduki kutoka shehena ya buggy, kiti cha mpiga risasi au ulinzi wa obiti. Hutaki — bonyeza ✕ au upuuze tu.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Mpelelezi mkongwe \"Bundi\" anatoa jukumu. Y — kubali (N — kataa). Nenda kwenye alama ya ★, ondoa walinzi na ubaki karibu na rubani sekunde 3 — atajiunga na kikosi chako.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Mstari wa mbele umekwama — Makao Makuu yanatoa mageuzi. Y — kubali. Shikilia kituo cha mawasiliano sekunde 8 bila maadui karibu: ramani ya adui inaonekana sekunde 60. Jenereta — minara ya adui kimya dakika 2. Katika hali ya Mwanastratejia — \"Mpe kikosi\". Adui naye anaweza: angalia ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Wenzako wanaomba msaada: kadi ya \"OMBI\" na alama ya ✋. Teketeza maadui karibu na kikosi kilichobanwa — upate zawadi. ✕ — ruka.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Shujaa \"Bundi\" anatoa jukumu — gusa \"Kubali\". Nenda ★, ondoa walinzi, kaa karibu na rubani.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Mstari wa mbele umekwama — gusa \"Kubali\" na ushikilie kituo cha mawasiliano sekunde 8: ramani ya adui itafunguka kwa dakika moja.",
