"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Vifaru vikuu vya vita: kanuni na bunduki. Consortium wana \"Bulldog\" (imara zaidi), Swarm wana \"Spider\" (kasi zaidi).",
"Heavy tank":"Kifaru kizito",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Mpiga risasi anayeruka kivyake: mwepesi, dhaifu, anaogopa kuangushwa kwa ndege.",
"Upgrade":"Uboreshaji",
"Longer, faster jetpacks for all infantry.":"Jetpack za masafa marefu na kasi zaidi kwa askari wote wa miguu.",
"Extractors mine more ore.":"Vichimbaji huchimba madini ghafi zaidi.",
"Army-wide levels: less damage taken / more damage dealt.":"Viwango kwa jeshi zima: madhara kidogo kwa wetu / madhara zaidi kwa adui.",
"Levels":"Viwango",
"Base":"Msingi",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Moyo wa msingi: vikosi, wahandisi, kapsuli, utafiti. Ukiupoteza, umeshindwa.",
"Produces: ":"Hutengeneza: ",
"Launch pad":"Jukwaa la kurusha",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Shimo karibu na Makao Makuu: kapsuli, makreti ya vifaa na walipuaji huanzia hapa kupitia lango la anga hadi lengo. Haiwezekani kujenga juu yake.",
"Economy":"Uchumi",
"Key building":"Jengo muhimu",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Sehemu dhaifu — nyuma (injini): madhara ×{0}. Kanuni, minara 2 ya bunduki, kasha la roketi; hugeuka polepole sana — mzunguke upande.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Sehemu dhaifu — kiini kinachong'aa chini ya tumbo: madhara kutoka chini ×{0}. Mwale wa upotoshaji na kukanyaga eneo; hupita juu ya vizuizi — weka umbali, msikusanyike pamoja.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Dhidi yake: mabomu ya angani na mizinga (×{0}), roketi (×{1}), mabomu ya zulia; risasi hazimdhuru karibu kabisa (×{2}).",
"Faction":"Kundi",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Mashine za haraka, makundi ya droni, mahandaki na kujiponya. Askari wepesi zaidi lakini wa kasi; kanuni na reli hupiga kwa nguvu zaidi.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Askari wazito wa miguu wenye ganda la nguvu, vizuizi vya zege, ukarabati na mizinga. Polepole lakini imara zaidi.",
"Infantry HP":"Askari wa miguu: nguvu",
"Infantry speed":"Askari wa miguu: kasi",
"Jetpacks":"Mikoba ya roketi",
"Weapon damage: ":"Madhara ya silaha: ",
