"Boss: ":"Bosi: ",
"Commander: regen burst, jet leap.":"Kamanda: mlipuko wa kujiponya, kuruka kwa mkoba wa roketi.",
"Commander: field medic, mini barrier.":"Kamanda: tabibu wa uwanjani, kizuizi kidogo.",
"Wave 1 · v7.8":"Wimbi 1 · v7.8",
"Wave 2 · v8.6":"Wimbi 2 · v8.6",
"Autumn · v8.10":"Vuli · v8.10",
