"Want to lead one squad?":"Unataka kuongoza kikosi kimoja?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"Fungua hali ya Kamanda: kamera iko juu ya kikosi, gusa mahali pa kwenda.",
"Yes":"Ndiyo",
