"You run and shoot yourself. That is how you have played so far.":"Unakimbia na kupiga risasi mwenyewe. Ndivyo ulivyocheza hadi sasa.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Unatazama kutoka juu na kuamuru jeshi lote: unajenga kituo, unatuma vikosi. Jeshi pia hupigana lenyewe hata bila wewe.",
